insert into public.nodes (id, course_id, stage, title, deps, summary, pitfall, flash, sort) values
  ('mi1111-gioi-han', 'mi1111', 0, 'Giới hạn hàm số', '{}'::text[], 'Giới hạn mô tả giá trị mà f(x) tiến tới khi x tiến tới a. Hàm số không cần xác định tại a.', 'Nhầm giới hạn tại a với giá trị f(a). Hai đại lượng này chỉ bằng nhau khi hàm liên tục tại a.', '[{"q":"Giới hạn của sin(x)/x khi x tiến tới 0 bằng bao nhiêu?","a":"Bằng 1, dù biểu thức không xác định tại x = 0."}]'::jsonb, 0),
  ('mi1111-lien-tuc', 'mi1111', 0, 'Hàm số liên tục', array['mi1111-gioi-han'], 'Hàm liên tục tại a khi giới hạn tại a tồn tại và bằng f(a).', 'Cho rằng hàm có giới hạn tại a thì chắc chắn liên tục tại a.', '[{"q":"Hàm f(x) = |x| có liên tục tại 0 không?","a":"Có. Giới hạn hai phía đều bằng 0 và f(0) = 0, dù hàm không có đạo hàm tại đó."}]'::jsonb, 1),
  ('mi1141-ma-tran', 'mi1141', 0, 'Ma trận và phép toán', '{}'::text[], 'Ma trận là bảng số chữ nhật. Phép nhân AB cần số cột của A bằng số hàng của B.', 'Cho rằng AB = BA. Phép nhân ma trận nói chung không giao hoán.', '[{"q":"A cỡ 2×3, B cỡ 3×4 thì AB có cỡ nào?","a":"Cỡ 2×4. Tích BA không xác định."}]'::jsonb, 0),
  ('mi1141-dinh-thuc', 'mi1141', 0, 'Định thức', array['mi1141-ma-tran'], 'Định thức chỉ có với ma trận vuông. Định thức khác 0 khi và chỉ khi ma trận khả nghịch.', 'Dùng det(A + B) = det(A) + det(B). Công thức này sai.', '[{"q":"Đổi chỗ hai hàng thì định thức thay đổi thế nào?","a":"Đổi dấu."}]'::jsonb, 1),
  ('it1110-bieu-dien', 'it1110', 0, 'Biểu diễn số trong máy tính', '{}'::text[], 'Máy tính lưu số bằng bit. Số nguyên có dấu thường dùng mã bù 2, số thực dùng dấu phẩy động.', 'Cho rằng 0.1 + 0.2 luôn đúng bằng 0.3. Số thực chỉ được lưu gần đúng.', '[{"q":"Số nguyên có dấu 8 bit biểu diễn được khoảng nào?","a":"Từ −128 đến 127 với mã bù 2."}]'::jsonb, 0),
  ('it1110-bien-kieu', 'it1110', 0, 'Biến và kiểu dữ liệu trong C', array['it1110-bieu-dien'], 'Kiểu dữ liệu quyết định kích thước và cách hiểu vùng nhớ. Biến phải khai báo trước khi dùng.', 'Chia hai số nguyên rồi mong được số thực: 5 / 2 trong C cho kết quả 2.', '[{"q":"Giá trị của (float)5 / 2 là gì?","a":"2.5, vì ép kiểu trước khi chia."}]'::jsonb, 1),
  ('it3011-do-phuc-tap', 'it3011', 0, 'Độ phức tạp thuật toán', '{}'::text[], 'Ký hiệu O mô tả chặn trên tốc độ tăng của thời gian chạy khi kích thước dữ liệu tăng.', 'So sánh hai thuật toán chỉ bằng O mà quên hằng số và kích thước dữ liệu thực tế.', '[{"q":"Hai vòng lặp lồng nhau, mỗi vòng n lần, có độ phức tạp nào?","a":"O(n²)."}]'::jsonb, 0),
  ('it3070-tien-trinh', 'it3070', 0, 'Tiến trình', '{}'::text[], 'Tiến trình là chương trình đang chạy, có không gian địa chỉ riêng và khối điều khiển tiến trình.', 'Nhầm chương trình với tiến trình. Một chương trình có thể có nhiều tiến trình.', '[{"q":"Sau lời gọi fork(), giá trị trả về ở tiến trình con là gì?","a":"Bằng 0. Tiến trình cha nhận mã của tiến trình con."}]'::jsonb, 0),
  ('it3080-mo-hinh', 'it3080', 0, 'Mô hình phân tầng', '{}'::text[], 'TCP/IP chia thành các tầng, mỗi tầng dùng dịch vụ của tầng dưới và phục vụ tầng trên.', 'Nhầm tầng của thiết bị: switch làm việc chủ yếu ở tầng liên kết, router ở tầng mạng.', '[{"q":"Đơn vị dữ liệu của tầng giao vận TCP gọi là gì?","a":"Segment."}]'::jsonb, 0),
  ('it3090-mo-hinh-er', 'it3090', 0, 'Mô hình thực thể - liên kết', '{}'::text[], 'Mô hình ER mô tả thực thể, thuộc tính và liên kết trước khi thiết kế bảng.', 'Biến thuộc tính đa trị thành một cột chứa nhiều giá trị ngăn bằng dấu phẩy.', '[{"q":"Liên kết nhiều - nhiều chuyển sang bảng thế nào?","a":"Tạo bảng trung gian chứa khóa của hai thực thể."}]'::jsonb, 0)
insert into public.nodes (id, course_id, stage, title, deps, summary, pitfall, flash, sort) values
  ('mi1111-dao-ham', 'mi1111', 1, 'Đạo hàm và vi phân', array['mi1111-lien-tuc'], 'Đạo hàm là tốc độ thay đổi tức thời, bằng hệ số góc của tiếp tuyến. Có đạo hàm thì liên tục.', 'Suy ngược: liên tục thì có đạo hàm. Điều này sai, ví dụ |x| tại 0.', '[{"q":"Đạo hàm của sin(x²) là gì?","a":"2x·cos(x²), theo quy tắc hàm hợp."}]'::jsonb, 2),
  ('mi1141-he-pt', 'mi1141', 1, 'Hệ phương trình tuyến tính', array['mi1141-dinh-thuc'], 'Hệ có nghiệm khi hạng ma trận hệ số bằng hạng ma trận mở rộng (Kronecker - Capelli).', 'Thấy số phương trình bằng số ẩn thì kết luận hệ có nghiệm duy nhất.', '[{"q":"Hệ thuần nhất luôn có nghiệm nào?","a":"Nghiệm tầm thường, mọi ẩn bằng 0."}]'::jsonb, 2),
  ('it1110-dieu-khien', 'it1110', 1, 'Rẽ nhánh và vòng lặp', array['it1110-bien-kieu'], 'if, switch chọn nhánh thực hiện; for, while, do - while lặp lại một khối lệnh.', 'Viết if (a = 5) thay cho if (a == 5). Phép gán làm điều kiện luôn đúng.', '[{"q":"do - while khác while ở điểm nào?","a":"do - while thực hiện thân vòng lặp ít nhất một lần."}]'::jsonb, 2),
  ('it3011-danh-sach', 'it3011', 1, 'Danh sách, ngăn xếp, hàng đợi', array['it3011-do-phuc-tap'], 'Ngăn xếp vào sau ra trước, hàng đợi vào trước ra trước. Danh sách liên kết chèn nhanh khi đã có vị trí.', 'Cho rằng danh sách liên kết truy cập phần tử thứ k nhanh như mảng. Thực tế là O(k).', '[{"q":"Cấu trúc nào phù hợp để kiểm tra dấu ngoặc cân bằng?","a":"Ngăn xếp."}]'::jsonb, 1),
  ('it3011-sap-xep', 'it3011', 1, 'Sắp xếp', array['it3011-do-phuc-tap'], 'Merge sort luôn O(n log n). Quick sort trung bình O(n log n) nhưng trường hợp xấu là O(n²).', 'Nghĩ quick sort luôn nhanh hơn merge sort trong mọi trường hợp.', '[{"q":"Thuật toán sắp xếp ổn định nghĩa là gì?","a":"Giữ nguyên thứ tự tương đối của các phần tử có khóa bằng nhau."}]'::jsonb, 2),
  ('it3070-luong', 'it3070', 1, 'Luồng', array['it3070-tien-trinh'], 'Các luồng trong một tiến trình dùng chung bộ nhớ nhưng có ngăn xếp và thanh ghi riêng.', 'Cho rằng biến toàn cục được cập nhật an toàn khi nhiều luồng cùng ghi.', '[{"q":"Luồng có dùng chung ngăn xếp không?","a":"Không, mỗi luồng có ngăn xếp riêng."}]'::jsonb, 1),
  ('it3070-lap-lich', 'it3070', 1, 'Lập lịch CPU', array['it3070-tien-trinh'], 'FCFS, SJF, Round Robin, ưu tiên là các chiến lược chọn tiến trình được chạy tiếp.', 'Cho rằng lượng tử thời gian càng nhỏ càng tốt. Quá nhỏ thì tốn chi phí chuyển ngữ cảnh.', '[{"q":"Thuật toán nào có thời gian chờ trung bình nhỏ nhất nếu biết trước thời gian chạy?","a":"SJF, với các tiến trình cùng đến một lúc."}]'::jsonb, 3),
  ('it3080-ung-dung', 'it3080', 1, 'Tầng ứng dụng: DNS và HTTP', array['it3080-mo-hinh'], 'DNS đổi tên miền thành địa chỉ IP. HTTP trao đổi yêu cầu và phản hồi giữa trình duyệt và máy chủ.', 'Cho rằng DNS chỉ dùng UDP. DNS cũng dùng TCP khi phản hồi lớn hoặc chuyển vùng.', '[{"q":"Mã 301 và 302 khác nhau thế nào?","a":"301 là chuyển hướng vĩnh viễn, 302 là tạm thời."}]'::jsonb, 1),
  ('it3080-giao-van', 'it3080', 1, 'Tầng giao vận: TCP và UDP', array['it3080-mo-hinh'], 'TCP bảo đảm thứ tự và truyền lại; UDP gửi nhanh, không bảo đảm.', 'Nhầm điều khiển luồng (bảo vệ bên nhận) với điều khiển tắc nghẽn (bảo vệ mạng).', '[{"q":"Bắt tay ba bước gồm những gói nào?","a":"SYN, SYN-ACK, ACK."}]'::jsonb, 2),
  ('it3090-sql', 'it3090', 1, 'Truy vấn SQL', array['it3090-mo-hinh-er'], 'SELECT, JOIN, GROUP BY, HAVING là các thành phần chính của truy vấn.', 'Dùng WHERE để lọc kết quả hàm gộp. Phải dùng HAVING.', '[{"q":"LEFT JOIN khác INNER JOIN ở điểm nào?","a":"LEFT JOIN giữ mọi dòng bên trái, kể cả khi không có dòng khớp."}]'::jsonb, 1)
insert into public.nodes (id, course_id, stage, title, deps, summary, pitfall, flash, sort) values
  ('mi1111-tich-phan', 'mi1111', 2, 'Tích phân xác định', array['mi1111-dao-ham'], 'Tích phân xác định là giới hạn của tổng Riemann. Công thức Newton - Leibniz nối nó với nguyên hàm.', 'Coi tích phân luôn là diện tích. Phần đồ thị nằm dưới trục hoành cho giá trị âm.', '[{"q":"Tích phân của x từ 0 đến 2 bằng bao nhiêu?","a":"Bằng 2, vì nguyên hàm là x²/2."}]'::jsonb, 3),
  ('mi1141-khong-gian', 'mi1141', 2, 'Không gian vectơ', array['mi1141-he-pt'], 'Cơ sở là hệ vectơ độc lập tuyến tính và sinh ra cả không gian. Số vectơ trong cơ sở là số chiều.', 'Cho rằng hệ sinh nào cũng là cơ sở. Hệ sinh còn phải độc lập tuyến tính.', '[{"q":"Ba vectơ bất kỳ trong mặt phẳng R² có thể độc lập tuyến tính không?","a":"Không, vì R² chỉ có 2 chiều."}]'::jsonb, 3),
  ('it1110-mang-ham', 'it1110', 2, 'Mảng và hàm', array['it1110-dieu-khien'], 'Mảng lưu nhiều phần tử cùng kiểu liên tiếp. Khi truyền vào hàm, mảng được truyền dưới dạng con trỏ.', 'Truy cập phần tử ngoài mảng. C không báo lỗi, hành vi không xác định.', '[{"q":"int a[5] có chỉ số hợp lệ nào?","a":"Từ 0 đến 4."}]'::jsonb, 3),
  ('it3011-cay', 'it3011', 2, 'Cây nhị phân tìm kiếm', array['it3011-danh-sach'], 'Khóa ở cây con trái nhỏ hơn gốc, cây con phải lớn hơn gốc. Duyệt giữa cho dãy tăng dần.', 'Cho rằng tìm kiếm luôn O(log n). Cây lệch hẳn một phía thì thành O(n).', '[{"q":"Duyệt giữa một cây nhị phân tìm kiếm cho kết quả gì?","a":"Dãy khóa tăng dần."}]'::jsonb, 3),
  ('it3070-dong-bo', 'it3070', 2, 'Đồng bộ và tắc nghẽn', array['it3070-luong'], 'Khóa và semaphore bảo vệ vùng găng. Tắc nghẽn cần đủ 4 điều kiện: loại trừ, giữ và chờ, không chiếm đoạt, chờ vòng.', 'Chỉ khóa khi ghi mà không khóa khi đọc dữ liệu dùng chung.', '[{"q":"Phá điều kiện chờ vòng bằng cách nào?","a":"Quy định thứ tự xin khóa thống nhất cho mọi luồng."}]'::jsonb, 2),
  ('it3080-dia-chi-ip', 'it3080', 2, 'Địa chỉ IP và chia mạng con', array['it3080-giao-van', 'it3080-ung-dung'], 'Mặt nạ mạng chia địa chỉ thành phần mạng và phần máy. CIDR viết dạng /n.', 'Quên trừ địa chỉ mạng và địa chỉ quảng bá khi đếm số máy.', '[{"q":"Mạng /26 có bao nhiêu địa chỉ dùng cho máy?","a":"62, vì 2⁶ − 2 = 62."}]'::jsonb, 3),
  ('it3090-chuan-hoa', 'it3090', 2, 'Phụ thuộc hàm và chuẩn hóa', array['it3090-sql'], 'Chuẩn hóa giảm dư thừa và bất thường khi cập nhật. 3NF loại phụ thuộc bắc cầu vào khóa.', 'Tách bảng tùy ý mà làm mất thông tin khi kết nối lại.', '[{"q":"Quan hệ ở 2NF nhưng có phụ thuộc bắc cầu thì vi phạm chuẩn nào?","a":"3NF."}]'::jsonb, 2),
  ('it3090-chi-muc', 'it3090', 2, 'Chỉ mục', array['it3090-sql'], 'Chỉ mục B-tree tăng tốc tìm kiếm theo khóa và theo khoảng, đổi lại ghi chậm hơn.', 'Tạo chỉ mục cho mọi cột. Mỗi chỉ mục làm chậm thao tác ghi và tốn bộ nhớ.', '[{"q":"Vì sao LIKE ''%abc'' thường không dùng được chỉ mục B-tree?","a":"Vì không biết tiền tố để dò trong cây."}]'::jsonb, 3)
insert into public.nodes (id, course_id, stage, title, deps, summary, pitfall, flash, sort) values
  ('mi1111-suy-rong', 'mi1111', 3, 'Tích phân suy rộng', array['mi1111-tich-phan'], 'Tích phân suy rộng có cận vô hạn hoặc hàm không bị chặn, được định nghĩa qua giới hạn.', 'Thấy hàm tiến về 0 thì kết luận tích phân hội tụ. Hàm 1/x trên [1, +∞) vẫn phân kỳ.', '[{"q":"Tích phân của 1/x² từ 1 đến vô cùng hội tụ hay phân kỳ?","a":"Hội tụ và bằng 1."}]'::jsonb, 4),
  ('mi1141-tri-rieng', 'mi1141', 3, 'Trị riêng và vectơ riêng', array['mi1141-khong-gian'], 'λ là trị riêng của A nếu có vectơ v khác 0 sao cho Av = λv. Tìm λ từ det(A − λI) = 0.', 'Nhận vectơ 0 làm vectơ riêng. Vectơ riêng phải khác 0.', '[{"q":"Ma trận có trị riêng bằng 0 thì có khả nghịch không?","a":"Không, vì khi đó định thức bằng 0."}]'::jsonb, 4),
  ('it1110-con-tro', 'it1110', 3, 'Con trỏ', array['it1110-mang-ham'], 'Con trỏ lưu địa chỉ. Toán tử & lấy địa chỉ, toán tử * truy cập giá trị tại địa chỉ.', 'Dùng con trỏ chưa khởi tạo hoặc đã giải phóng.', '[{"q":"Vì sao hàm swap(int a, int b) không đổi được hai biến bên ngoài?","a":"Vì C truyền tham trị. Cần truyền con trỏ tới hai biến."}]'::jsonb, 4),
  ('it3011-do-thi', 'it3011', 3, 'Đồ thị và tìm đường', array['it3011-cay', 'it3011-sap-xep'], 'BFS tìm đường ít cạnh nhất. Dijkstra tìm đường ngắn nhất khi trọng số không âm.', 'Dùng Dijkstra cho đồ thị có cạnh trọng số âm.', '[{"q":"Muốn tìm đường ngắn nhất khi có cạnh âm, không có chu trình âm, dùng thuật toán nào?","a":"Bellman - Ford."}]'::jsonb, 4),
  ('it3070-bo-nho-ao', 'it3070', 3, 'Bộ nhớ ảo và phân trang', array['it3070-dong-bo', 'it3070-lap-lich'], 'Mỗi tiến trình thấy không gian địa chỉ riêng. Bảng trang ánh xạ trang ảo sang khung vật lý.', 'Cho rằng lỗi trang luôn là lỗi chương trình. Thường nó chỉ báo cần nạp trang vào bộ nhớ.', '[{"q":"TLB dùng để làm gì?","a":"Lưu tạm các ánh xạ trang gần đây để dịch địa chỉ nhanh hơn."}]'::jsonb, 4),
  ('it3080-dinh-tuyen', 'it3080', 3, 'Định tuyến', array['it3080-dia-chi-ip'], 'Định tuyến trạng thái liên kết (OSPF) và vectơ khoảng cách (RIP) là hai nhóm chính trong một hệ tự trị.', 'Cho rằng router chọn dòng khớp đầu tiên. Router chọn dòng khớp tiền tố dài nhất.', '[{"q":"BGP dùng ở đâu?","a":"Giữa các hệ tự trị trên Internet."}]'::jsonb, 4),
  ('it3090-giao-dich', 'it3090', 3, 'Giao dịch', array['it3090-chuan-hoa', 'it3090-chi-muc'], 'Giao dịch bảo đảm ACID: nguyên tử, nhất quán, cô lập, bền vững.', 'Cho rằng mức cô lập mặc định luôn ngăn mọi bất thường khi chạy song song.', '[{"q":"Đọc bẩn là gì?","a":"Đọc dữ liệu mà giao dịch khác chưa commit."}]'::jsonb, 4)
