insert into public.exams (course_id, term, data) values
  ('mi1111', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Giới hạn của sin(x)/x khi x tiến tới 0 bằng bao nhiêu?","a":"Bằng 1, dù biểu thức không xác định tại x = 0.","node":"mi1111-gioi-han"},{"q":"Hàm f(x) = |x| có liên tục tại 0 không?","a":"Có. Giới hạn hai phía đều bằng 0 và f(0) = 0, dù hàm không có đạo hàm tại đó.","node":"mi1111-lien-tuc"},{"q":"Đạo hàm của sin(x²) là gì?","a":"2x·cos(x²), theo quy tắc hàm hợp.","node":"mi1111-dao-ham"}]}}'::jsonb),
  ('mi1111', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Đạo hàm của sin(x²) là gì?","a":"2x·cos(x²), theo quy tắc hàm hợp.","node":"mi1111-dao-ham"},{"q":"Tích phân của x từ 0 đến 2 bằng bao nhiêu?","a":"Bằng 2, vì nguyên hàm là x²/2.","node":"mi1111-tich-phan"},{"q":"Tích phân của 1/x² từ 1 đến vô cùng hội tụ hay phân kỳ?","a":"Hội tụ và bằng 1.","node":"mi1111-suy-rong"}]}}'::jsonb),
  ('mi1141', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"A cỡ 2×3, B cỡ 3×4 thì AB có cỡ nào?","a":"Cỡ 2×4. Tích BA không xác định.","node":"mi1141-ma-tran"},{"q":"Đổi chỗ hai hàng thì định thức thay đổi thế nào?","a":"Đổi dấu.","node":"mi1141-dinh-thuc"},{"q":"Hệ thuần nhất luôn có nghiệm nào?","a":"Nghiệm tầm thường, mọi ẩn bằng 0.","node":"mi1141-he-pt"}]}}'::jsonb),
  ('mi1141', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Hệ thuần nhất luôn có nghiệm nào?","a":"Nghiệm tầm thường, mọi ẩn bằng 0.","node":"mi1141-he-pt"},{"q":"Ba vectơ bất kỳ trong mặt phẳng R² có thể độc lập tuyến tính không?","a":"Không, vì R² chỉ có 2 chiều.","node":"mi1141-khong-gian"},{"q":"Ma trận có trị riêng bằng 0 thì có khả nghịch không?","a":"Không, vì khi đó định thức bằng 0.","node":"mi1141-tri-rieng"}]}}'::jsonb),
  ('it1110', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Số nguyên có dấu 8 bit biểu diễn được khoảng nào?","a":"Từ −128 đến 127 với mã bù 2.","node":"it1110-bieu-dien"},{"q":"Giá trị của (float)5 / 2 là gì?","a":"2.5, vì ép kiểu trước khi chia.","node":"it1110-bien-kieu"},{"q":"do - while khác while ở điểm nào?","a":"do - while thực hiện thân vòng lặp ít nhất một lần.","node":"it1110-dieu-khien"}]}}'::jsonb),
  ('it1110', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"do - while khác while ở điểm nào?","a":"do - while thực hiện thân vòng lặp ít nhất một lần.","node":"it1110-dieu-khien"},{"q":"int a[5] có chỉ số hợp lệ nào?","a":"Từ 0 đến 4.","node":"it1110-mang-ham"},{"q":"Vì sao hàm swap(int a, int b) không đổi được hai biến bên ngoài?","a":"Vì C truyền tham trị. Cần truyền con trỏ tới hai biến.","node":"it1110-con-tro"}]}}'::jsonb),
  ('it3011', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Hai vòng lặp lồng nhau, mỗi vòng n lần, có độ phức tạp nào?","a":"O(n²).","node":"it3011-do-phuc-tap"},{"q":"Cấu trúc nào phù hợp để kiểm tra dấu ngoặc cân bằng?","a":"Ngăn xếp.","node":"it3011-danh-sach"},{"q":"Thuật toán sắp xếp ổn định nghĩa là gì?","a":"Giữ nguyên thứ tự tương đối của các phần tử có khóa bằng nhau.","node":"it3011-sap-xep"}]}}'::jsonb),
  ('it3011', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Thuật toán sắp xếp ổn định nghĩa là gì?","a":"Giữ nguyên thứ tự tương đối của các phần tử có khóa bằng nhau.","node":"it3011-sap-xep"},{"q":"Duyệt giữa một cây nhị phân tìm kiếm cho kết quả gì?","a":"Dãy khóa tăng dần.","node":"it3011-cay"},{"q":"Muốn tìm đường ngắn nhất khi có cạnh âm, không có chu trình âm, dùng thuật toán nào?","a":"Bellman - Ford.","node":"it3011-do-thi"}]}}'::jsonb),
  ('it3070', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Sau lời gọi fork(), giá trị trả về ở tiến trình con là gì?","a":"Bằng 0. Tiến trình cha nhận mã của tiến trình con.","node":"it3070-tien-trinh"},{"q":"Luồng có dùng chung ngăn xếp không?","a":"Không, mỗi luồng có ngăn xếp riêng.","node":"it3070-luong"},{"q":"Phá điều kiện chờ vòng bằng cách nào?","a":"Quy định thứ tự xin khóa thống nhất cho mọi luồng.","node":"it3070-dong-bo"}]}}'::jsonb),
  ('it3070', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Phá điều kiện chờ vòng bằng cách nào?","a":"Quy định thứ tự xin khóa thống nhất cho mọi luồng.","node":"it3070-dong-bo"},{"q":"Thuật toán nào có thời gian chờ trung bình nhỏ nhất nếu biết trước thời gian chạy?","a":"SJF, với các tiến trình cùng đến một lúc.","node":"it3070-lap-lich"},{"q":"TLB dùng để làm gì?","a":"Lưu tạm các ánh xạ trang gần đây để dịch địa chỉ nhanh hơn.","node":"it3070-bo-nho-ao"}]}}'::jsonb),
  ('it3080', 'mid', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Đơn vị dữ liệu của tầng giao vận TCP gọi là gì?","a":"Segment.","node":"it3080-mo-hinh"},{"q":"Mã 301 và 302 khác nhau thế nào?","a":"301 là chuyển hướng vĩnh viễn, 302 là tạm thời.","node":"it3080-ung-dung"},{"q":"Bắt tay ba bước gồm những gói nào?","a":"SYN, SYN-ACK, ACK.","node":"it3080-giao-van"}]}}'::jsonb),
  ('it3080', 'final', '{"papers":[],"note":"","practice":{"title":"Đề tự luyện (mẫu)","time":"30 phút","questions":[{"q":"Bắt tay ba bước gồm những gói nào?","a":"SYN, SYN-ACK, ACK.","node":"it3080-giao-van"},{"q":"Mạng /26 có bao nhiêu địa chỉ dùng cho máy?","a":"62, vì 2⁶ − 2 = 62.","node":"it3080-dia-chi-ip"},{"q":"BGP dùng ở đâu?","a":"Giữa các hệ tự trị trên Internet.","node":"it3080-dinh-tuyen"}]}}'::jsonb),
