  ('mau-1', 'it3011-cay', 'it3011', 'Sóc Kiên Nhẫn', 'Khi nào cây nhị phân tìm kiếm bị lệch?', 'Mình chèn dãy tăng dần thì cây thành một đường thẳng, có cách nào tránh không?', true, now() - interval '9 hours'),
