  ('mau-3', 'it3090-chuan-hoa', 'it3090', 'Cú Mèo Tri Thức', 'Chuẩn hóa đến mức nào là đủ?', 'Bài tập lớn của mình tách tới BCNF thì phải nối rất nhiều bảng.', true, now() - interval '27 hours'),
  ('mau-4', 'it3080-dia-chi-ip', 'it3080', 'Rái Cá Chăm Chỉ', 'Chia mạng con khi số máy không đều thì làm sao?', 'Đề cho 3 phòng có 50, 20 và 10 máy.', true, now() - interval '36 hours'),
  ('mau-5', 'it3070-dong-bo', 'it3070', 'Hải Ly Tìm Hiểu', 'Semaphore khác mutex thế nào?', '', true, now() - interval '45 hours'),
  ('mau-6', 'it1110-con-tro', 'it1110', 'Chim Sẻ Đi Học', 'Con trỏ và mảng có giống nhau không?', 'Mình thấy a[i] và *(a + i) ra cùng kết quả.', true, now() - interval '54 hours'),
  ('mau-7', 'mi1111-suy-rong', 'mi1111', 'Gấu Học Hỏi', 'Xét hội tụ tích phân suy rộng bắt đầu từ đâu?', '', true, now() - interval '63 hours'),
  ('mau-8', 'mi1141-tri-rieng', 'mi1141', 'Mèo Tò Mò', 'Ma trận nào cũng chéo hóa được phải không?', 'Mình gặp ma trận có trị riêng bội 2 mà chỉ tìm được một vectơ riêng.', true, now() - interval '72 hours')
insert into public.replies (id, question_id, body, alias, created_at) values
  ('mau-tl-1', 'mau-1', 'Bạn xem cây cân bằng như AVL hoặc đỏ đen, chúng tự xoay sau mỗi lần chèn.', 'Cáo Nhỏ Kiên Trì', now() - interval '8 hours'),
  ('mau-tl-2', 'mau-2', 'Bản cài đặt thông thường không ổn định, vì đổi chỗ các phần tử ở xa nhau.', 'Cáo Nhỏ Kiên Trì', now() - interval '16 hours'),
  ('mau-tl-3', 'mau-3', 'Thường 3NF là đủ cho bài tập lớn, chỉ tách thêm khi thấy bất thường cập nhật thật sự.', 'Cáo Nhỏ Kiên Trì', now() - interval '24 hours'),
  ('mau-tl-4', 'mau-4', 'Dùng VLSM: cấp cho phòng lớn nhất trước, lần lượt /26, /27, /28.', 'Cáo Nhỏ Kiên Trì', now() - interval '32 hours'),
  ('mau-tl-5', 'mau-5', 'Mutex có chủ sở hữu và chỉ cho một luồng vào; semaphore đếm được số luồng.', 'Cáo Nhỏ Kiên Trì', now() - interval '40 hours'),
  ('mau-tl-6', 'mau-6', 'Tên mảng tự chuyển thành con trỏ trong nhiều biểu thức, nhưng sizeof của chúng khác nhau.', 'Cáo Nhỏ Kiên Trì', now() - interval '48 hours')
